def transaction_policy_shape_ok(policy: object) -> bool:
    """交易策略条目形状：mode 仅 hot/cold、max_delta 为非布尔正整数、
    allowed_assets 为非空数组且每项匹配安全 id。"""
    if not isinstance(policy, dict):
