def _is_lower_hex_32(value: object) -> bool:
    """恰为 64 位小写 hex（32 字节）的字符串判定。"""
    return (
        isinstance(value, str)
        and len(value) == 64
        and all(c in "0123456789abcdef" for c in value)
    )


def chain_report_shape_ok(report: object) -> bool:
    """链上确认数报告 B 的形状：恰含 chain_id/tx_id/block_height/
    block_hash/confirmations 五键，chain_id 为安全标识，tx_id 与
    block_hash 为 64 位小写 hex，block_height/confirmations 为非布尔
    非负整数。"""
    if not isinstance(report, dict):
        return False
    if set(report) != {
        "chain_id",
        "tx_id",
        "block_height",
        "block_hash",
        "confirmations",
    }:
        return False
    if not _valid_safe_id(report["chain_id"]):
        return False
    if not _is_lower_hex_32(report["tx_id"]):
        return False
    if not _is_lower_hex_32(report["block_hash"]):
        return False
    if not _is_plain_int(report["block_height"]) or report["block_height"] < 0:
        return False
    return _is_plain_int(report["confirmations"]) and report["confirmations"] >= 0


def chain_vote_shape_ok(vote: object) -> bool:
    """多源仲裁票 details 的形状：恰含 source/report/state 三键，source 为
    安全标识，report 为达门槛链上报告 B（chain_report 同形五字段），
    state 只能为 collecting/conflict/adopted。"""
    if not isinstance(vote, dict):
        return False
    if set(vote) != {"source", "report", "state"}:
        return False
    if not _valid_safe_id(vote["source"]):
        return False
    if not chain_report_shape_ok(vote["report"]):
        return False
    return vote["state"] in ("collecting", "conflict", "adopted")


def dispatch_reorg_confirmation_shape_ok(
    confirmation: object, dispatch_id: str
) -> bool:
    """重组补偿意图随附的确认进展视图 V 的形状：恰含
    dispatch_id/adapter_id/tx_id/block_height/block_hash/confirmations/
    state 七键，dispatch_id 即本补偿操作的 id，adapter_id 为安全标识，
    tx_id/block_hash 为 64 位小写 hex，block_height/confirmations 为
    非布尔非负整数，state 只能为 reorged。"""
    if not isinstance(confirmation, dict):
        return False
    if set(confirmation) != {
        "dispatch_id",
        "adapter_id",
        "tx_id",
        "block_height",
        "block_hash",
        "confirmations",
        "state",
    }:
        return False
    if confirmation["dispatch_id"] != dispatch_id:
        return False
    if not _valid_safe_id(confirmation["adapter_id"]):
        return False
    if not _is_lower_hex_32(confirmation["tx_id"]):
        return False
    if not _is_lower_hex_32(confirmation["block_hash"]):
        return False
    if (
        not _is_plain_int(confirmation["block_height"])
        or confirmation["block_height"] < 0
    ):
        return False
    if (
        not _is_plain_int(confirmation["confirmations"])
        or confirmation["confirmations"] < 0
    ):
        return False
    return confirmation["state"] == "reorged"


def _asset_operation_shape_ok(key: str, record: object) -> bool:
    """资产操作条目形状：必须含合法 operation_id/asset_id、非布尔整数
    delta、state 只能为 pending/committed/cancelled；服务正常写入还带
    非布尔整数 balance/version 快照，若存在则同样必须为非布尔整数。"""
    if not isinstance(record, dict):
        return False
    operation_id = record.get("operation_id")
    asset_id = record.get("asset_id")
    if not _valid_safe_id(operation_id) or operation_id != key:
        return False
    if not _valid_safe_id(asset_id):
        return False
    if not _is_plain_int(record.get("delta")) or record.get("delta") == 0:
        return False
    if record.get("state") not in ("pending", "committed", "cancelled"):
        return False
    for optional_int in ("balance", "version"):
        if optional_int in record and not _is_plain_int(
            record[optional_int]
        ):
            return False
    return True


class DuplicateWalletError(Exception):
    """wallet_id 已存在。"""


class RecoveryError(Exception):
    """启动/运行时恢复无法把磁盘现场对账到一致状态。

    触发即说明数据目录损坏或被外部篡改，继续服务可能暴露半完成状态或
    写错密钥，因此调用方必须阻止服务就绪（fail-closed），不得静默跳过。
    """


class CorruptDataError(ValueError):
